import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  CircularProgress,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';
import ScrollableTableContainer from '../shared/ScrollableTableContainer';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';

const authHeaders = () => ({ Authorization: `Bearer ${localStorage.getItem('token')}` });

const PartnerVerificationQueuePanel: React.FC = () => {
  const [queue, setQueue] = useState<Array<Record<string, unknown>>>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res = await axios.get(buildApiUrl('/partner-account/verification-queue'), { headers: authHeaders() });
      setQueue(res.data?.data?.queue || []);
    } catch (e) {
      setError(axios.isAxiosError(e) ? e.response?.data?.message || e.message : 'Failed to load queue');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  if (loading) return <CircularProgress />;
  if (error) return <Alert severity="error">{error}</Alert>;

  return (
    <Box>
      <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>Verification queue</Typography>
      <ScrollableTableContainer>
        <Table size="small">
          <TableHead>
            <TableRow>
              <TableCell>Company</TableCell>
              <TableCell>Industry</TableCell>
              <TableCell>Status</TableCell>
              <TableCell>Carbon score</TableCell>
              <TableCell>Consent</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {queue.map((row) => (
              <TableRow key={String(row._id)}>
                <TableCell>{String(row.companyName || '—')}</TableCell>
                <TableCell>{String(row.industry || '—')}</TableCell>
                <TableCell><Chip size="small" label={String(row.status || '—')} /></TableCell>
                <TableCell>{String(row.carbonScore ?? '—')}</TableCell>
                <TableCell>
                  {(row.partnerDataConsent as { enabled?: boolean })?.enabled ? 'Yes' : 'No'}
                </TableCell>
              </TableRow>
            ))}
            {!queue.length ? (
              <TableRow><TableCell colSpan={5} align="center">Queue is empty</TableCell></TableRow>
            ) : null}
          </TableBody>
        </Table>
      </ScrollableTableContainer>
      <Button sx={{ mt: 2 }} size="small" onClick={load}>Refresh</Button>
    </Box>
  );
};

export default PartnerVerificationQueuePanel;
